from datetime import date, datetime, time
import unittest

import calendar_layout


DAY = date(2026, 11, 6)


def at(hour, minute=0):
    """Return a fixed local timestamp for geometry tests."""
    return datetime.combine(DAY, time(hour, minute))


class CalendarLayoutTests(unittest.TestCase):
    """Protect true time positions and prevent overlapping events from hiding one another."""

    def layout(self, intervals):
        """Use the app's 07:00–23:00 planning window."""
        return calendar_layout.interval_layout(DAY, intervals, time(7), time(23))

    def test_exact_offsets_and_durations(self):
        """Place a 75-minute appointment at its actual quarter-hour offset."""
        row = self.layout([(at(8, 15), at(9, 30))])[0]
        self.assertAlmostEqual(row['offset'], 75)
        self.assertAlmostEqual(row['minutes'], 75)
        self.assertEqual((row['lane'], row['lanes']), (0, 1))

    def test_clipping_omission_and_original_indices(self):
        """Clip both window edges, omit off-window blocks and preserve source references."""
        intervals = [(at(23), at(23, 30)), (at(6), at(8)), (at(22), at(23, 30))]
        original = list(intervals)
        rows = self.layout(intervals)
        self.assertEqual([row['index'] for row in rows], [1, 2])
        self.assertEqual([row['offset'] for row in rows], [0, 900])
        self.assertEqual([row['minutes'] for row in rows], [60, 60])
        self.assertEqual(intervals, original)

    def test_overlap_groups_and_touching_intervals(self):
        """Use two lanes for overlapping appointments and full width for the next group."""
        rows = self.layout([(at(8), at(10)), (at(9), at(11)), (at(11), at(12))])
        self.assertEqual([(row['lane'], row['lanes']) for row in rows], [(0, 2), (1, 2), (0, 1)])

    def test_nested_and_identical_appointments_remain_visible(self):
        """Give nested and identical events distinct lanes without altering their times."""
        intervals = [(at(8), at(12)), (at(8), at(12)), (at(9), at(10)), (at(10), at(11))]
        rows = self.layout(intervals)
        self.assertTrue(all(row['lanes'] == 3 for row in rows))
        for left in rows:
            for right in rows:
                if left['index'] >= right['index'] or left['lane'] != right['lane']:
                    continue
                self.assertLessEqual(left['offset'] + left['minutes'], right['offset'])

    def test_empty_and_invalid_intervals(self):
        """Accept an empty day and reject invalid event or timetable ranges."""
        self.assertEqual(self.layout([]), [])
        for beginning, ending in [(at(8), at(8)), (at(9), at(8))]:
            with self.assertRaises(ValueError):
                self.layout([(beginning, ending)])
        with self.assertRaises(ValueError):
            calendar_layout.interval_layout(DAY, [], time(23), time(7))
